    is_private boolean DEFAULT false NOT NULL,
    bio text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    preferred_message_language text DEFAULT 'en'::text NOT NULL,
    auto_translate_messages boolean DEFAULT true NOT NULL,
    show_original_messages boolean DEFAULT false NOT NULL,
    translation_updated_at timestamp with time zone,
    show_telegraph_dm boolean DEFAULT true NOT NULL,
