    travel_styles text[] DEFAULT '{}'::text[],
    travel_pace text,
    budget_style text,
    travel_group_style text[] DEFAULT '{}'::text[],
    looking_for text[] DEFAULT '{}'::text[],
    comfort_level text,
    availability_tags text[] DEFAULT '{}'::text[],
    planning_style text,
    public_social_links jsonb DEFAULT '{}'::jsonb,
    expo_push_token text,
    verification_status text DEFAULT 'unverified'::text NOT NULL,
    verified_at timestamp with time zone,
    verification_method text,
    verification_expires_at timestamp with time zone,
    highlights_last_viewed_at timestamp with time zone,
    tag_permission public.tag_permission_level DEFAULT 'anyone'::public.tag_permission_level NOT NULL,
    cover_photo_url text,
    account_status text DEFAULT 'active'::text NOT NULL,
    role text DEFAULT 'user'::text NOT NULL,
