    show_profile_picture_publicly boolean DEFAULT true NOT NULL,
    CONSTRAINT profiles_account_status_check CHECK ((account_status = ANY (ARRAY['active'::text, 'deactivated'::text, 'pending_deletion'::text, 'deleted'::text]))),
    CONSTRAINT profiles_role_check CHECK ((role = ANY (ARRAY['user'::text, 'admin'::text]))),
