--
-- Name: admin_set_profile_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_profile_role(target_user_id uuid, new_role text) RETURNS public.profiles
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  updated public.profiles;
BEGIN
  -- Belt and braces. EXECUTE is granted to service_role only (below), so a
  -- non-privileged caller should never reach this line; if a future migration
  -- widens that grant by accident, this check still holds.
  IF NOT public.caller_may_write_profile_role() THEN
    RAISE EXCEPTION 'admin_set_profile_role: caller is not privileged'
      USING ERRCODE = '42501';
  END IF;

  IF new_role IS NULL OR new_role NOT IN ('user', 'admin') THEN
    RAISE EXCEPTION 'admin_set_profile_role: unsupported role %', new_role
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.profiles
     SET role = new_role,
         updated_at = now()
   WHERE id = target_user_id
   RETURNING * INTO updated;

  IF updated IS NULL THEN
    RAISE EXCEPTION 'admin_set_profile_role: no profile with id %', target_user_id
      USING ERRCODE = 'P0002';
  END IF;

  RETURN updated;
END;
$$;


--
-- Name: FUNCTION admin_set_profile_role(target_user_id uuid, new_role text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_set_profile_role(target_user_id uuid, new_role text) IS 'The ONLY supported way to change profiles.role. service_role only.';


--
-- Name: append_stamp_cleanup_error_paths(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_stamp_cleanup_error_paths(p_job_id uuid, p_error text, p_paths text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE stamp_generation_queue
  SET cleanup_error       = p_error,
      cleanup_error_paths = (
        SELECT COALESCE(array_agg(DISTINCT p), '{}')
        FROM unnest(COALESCE(cleanup_error_paths, '{}') || COALESCE(p_paths, '{}')) AS p
      ),
      updated_at          = now()
  WHERE id = p_job_id;
$$;


