--
-- Name: caller_may_write_profile_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_may_write_profile_role() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT
    -- (a) PostgREST / explicit SET ROLE. 'authenticated' and 'anon' fail here.
    COALESCE(NULLIF(current_setting('role', true), ''), 'none')
      IN ('service_role', 'postgres', 'supabase_admin')
    -- (b) Direct superuser connection with no role GUC set.
    OR (
      COALESCE(NULLIF(current_setting('role', true), ''), 'none') = 'none'
      AND session_user IN ('postgres', 'supabase_admin')
    );
$$;


--
-- Name: FUNCTION caller_may_write_profile_role(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.caller_may_write_profile_role() IS 'True only for service_role, or a direct postgres/supabase_admin connection. Uses session_user (not current_user) so SECURITY DEFINER cannot launder a non-privileged caller into a privileged one.';


