-- Name: can_post_to_trip(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_post_to_trip(t_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select t_id is null or is_accepted_trip_member(t_id);
$$;


--
-- Name: can_see_location(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_location(viewer uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select case
    when viewer = target then true
    else exists (
      select 1 from user_location_privacy p
      join user_locations l on l.user_id = p.user_id
      where p.user_id = target and p.ghost_mode = false
        and l.updated_at > now() - make_interval(mins => p.stale_minutes)
        and (p.sharing = 'public' or (p.sharing = 'circle' and in_accepted_circle(viewer, target)))
    )
  end;
$$;


--
-- Name: can_see_post(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_post(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1 from posts p
    where p.id = p_id and (
      p.author_id = auth.uid()
      or (
        p.status = 'active' and p.deleted_at is null and (
          p.visibility = 'public'
          or (p.visibility = 'trip_only' and p.trip_id is not null and is_accepted_trip_member(p.trip_id))
        )
      )
    )
  );
$$;


--
-- Name: can_see_postcard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_postcard(pc_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1 from passport_postcards pc
    left join posts p on p.id = pc.post_id
    where pc.id = pc_id and (
      pc.user_id = auth.uid()
      or (
        pc.status = 'active' and pc.deleted_at is null and (
          pc.visibility = 'public'
          or (pc.visibility = 'trip_only' and p.trip_id is not null and is_accepted_trip_member(p.trip_id))
        )
      )
    )
  );
$$;


--
-- Name: can_see_trip(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_trip(t_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
      SELECT 1 FROM trips t WHERE t.id = t_id AND (
        t.owner_id = auth.uid()
        OR EXISTS (
          SELECT 1 FROM trip_members m
           WHERE m.trip_id = t.id
             AND m.user_id  = auth.uid()
             AND m.role = ANY (
               ARRAY['owner'::member_role, 'member'::member_role,
                     'co_host'::member_role, 'viewer'::member_role]
             )
        )
        OR (
          t.visibility = 'public'
          AND NOT viewer_is_blocked(t.owner_id)
        )
      )
    );
    $$;


--
-- Name: claim_invite_link_slot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_invite_link_slot(link_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE trip_invite_links
  SET use_count = use_count + 1
  WHERE id = link_id
    AND (max_uses IS NULL OR use_count < max_uses);

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count > 0;
END;
$$;


--
-- Name: claim_invite_link_slot_for_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_invite_link_slot_for_user(p_link_id uuid, p_user_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_trip_id       uuid;
  v_max_members   integer;
  v_member_count  bigint;
  v_updated_count integer;
BEGIN
  -- If an attempt row already exists this user previously claimed a slot that
  -- was never cleaned up (partial failure).  Signal the caller to retry the
  -- member insert without consuming another slot.
  IF EXISTS (
    SELECT 1 FROM trip_invite_link_attempts
    WHERE link_id = p_link_id AND user_id = p_user_id
  ) THEN
    RETURN 'already_attempted';
  END IF;

  -- Fast-path: if the trip already has max_members accepted members, skip the
  -- slot claim and INSERT attempt entirely.  This is a point-in-time read
  -- inside this transaction — it is an optimisation, not the atomic guard.
  -- The BEFORE INSERT trigger on trip_members is the authoritative gate.
  SELECT l.trip_id, t.max_members
  INTO   v_trip_id, v_max_members
  FROM   trip_invite_links l
  JOIN   trips t ON t.id = l.trip_id
  WHERE  l.id = p_link_id;

  IF NOT FOUND THEN
    -- Link deleted between handler's SELECT and here; treat as no slot.
    RETURN 'limit_reached';
  END IF;

  IF v_max_members IS NOT NULL THEN
    SELECT COUNT(*) INTO v_member_count
    FROM   trip_members
    WHERE  trip_id = v_trip_id
      AND  status  = 'accepted';

    IF v_member_count >= v_max_members THEN
      RETURN 'trip_full';
    END IF;
  END IF;

  -- Atomically increment use_count, gated on max_uses.
  UPDATE trip_invite_links
  SET    use_count = use_count + 1
  WHERE  id = p_link_id
    AND  (max_uses IS NULL OR use_count < max_uses);

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  IF v_updated_count = 0 THEN
    RETURN 'limit_reached';
  END IF;

  -- Record the claim so a retry can detect the partial-failure state.
  INSERT INTO trip_invite_link_attempts (link_id, user_id)
  VALUES (p_link_id, p_user_id)
  ON CONFLICT DO NOTHING;

  RETURN 'claimed';
END;
$$;


--
-- Name: cleanup_stale_invite_link_attempts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_stale_invite_link_attempts() RETURNS TABLE(link_id uuid, user_id uuid, claimed_at timestamp with time zone, trip_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
    DELETE FROM trip_invite_link_attempts a
    USING trip_invite_links til
    WHERE a.link_id = til.id
      AND EXISTS (
        SELECT 1
        FROM trip_members tm
        WHERE tm.trip_id = til.trip_id
          AND tm.user_id  = a.user_id
      )
    RETURNING
      a.link_id,
      a.user_id,
      a.claimed_at,
      til.trip_id;
END;
$$;


--
-- Name: create_live_place_recap(uuid, uuid, uuid, uuid, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_live_place_recap(p_owner_id uuid, p_place_day_id uuid, p_moment_id uuid, p_place_id uuid, p_title text, p_source_hash text, p_place_snapshot jsonb, p_sources jsonb DEFAULT '[]'::jsonb, p_chapters jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_recap live_place_recaps; v_version live_place_recap_versions;
BEGIN
  IF ((p_place_day_id IS NULL)::int + (p_moment_id IS NULL)::int) <> 1 THEN
    RAISE EXCEPTION 'exactly one recap parent is required';
  END IF;
  PERFORM validate_live_place_recap_evidence(
    p_owner_id, p_place_day_id, p_moment_id, p_place_id, p_place_snapshot, p_sources, p_chapters
  );
  INSERT INTO live_place_recaps (owner_id, place_day_id, moment_id, place_id)
    VALUES (p_owner_id, p_place_day_id, p_moment_id, p_place_id) RETURNING * INTO v_recap;
  INSERT INTO live_place_recap_versions (recap_id, version_number, title, source_hash, place_snapshot)
    VALUES (v_recap.id, 1, COALESCE(p_title, ''), p_source_hash, p_place_snapshot) RETURNING * INTO v_version;
  PERFORM recap_write_evidence(v_version.id, p_place_id, p_place_snapshot, p_sources, p_chapters);
  UPDATE live_place_recaps SET current_version_id = v_version.id, updated_at = now()
    WHERE id = v_recap.id RETURNING * INTO v_recap;
  RETURN jsonb_build_object('recap', to_jsonb(v_recap), 'version', to_jsonb(v_version));
END $$;


--
-- Name: decrement_discovery_place_saved_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_discovery_place_saved_count(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  new_count integer;
BEGIN
  UPDATE discovery_places
    SET saved_count = GREATEST(0, saved_count - 1)
  WHERE id = p_id
  RETURNING saved_count INTO new_count;

  RETURN COALESCE(new_count, 0);
END;
$$;


