--
-- Name: enforce_is_official_privileged(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_is_official_privileged() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Only a non-default value needs privilege. A normal signup inserting
    -- is_official = false (the column default) must not be blocked.
    IF COALESCE(NEW.is_official, false) IS DISTINCT FROM false
       AND NOT public.caller_may_write_profile_role() THEN
      RAISE EXCEPTION
        'profiles.is_official cannot be set on insert by this caller'
        USING ERRCODE = '42501',
              HINT = 'Use a service-role client, or connect directly as postgres/supabase_admin.';
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    -- BOTH directions. Granting and revoking official status are equally
    -- privileged; the previous guard only covered granting, which left the
    -- badge holder able to clear their own badge irreversibly.
    IF NEW.is_official IS DISTINCT FROM OLD.is_official
       AND NOT public.caller_may_write_profile_role() THEN
      RAISE EXCEPTION
        'profiles.is_official is not self-writable (attempted % -> %)', OLD.is_official, NEW.is_official
        USING ERRCODE = '42501',
              HINT = 'Use a service-role client, or connect directly as postgres/supabase_admin.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_is_official_privileged(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_is_official_privileged() IS 'Guards profiles.is_official in BOTH directions. Replaces enforce_is_official_service_role(), which rejected direct postgres connections (role GUC is ''none'', not ''postgres'') and guarded only false->true.';


--
-- Name: enforce_profile_role_privileged(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_profile_role_privileged() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- A user may create their own profile row (policy profiles_insert), so the
    -- INSERT path has to be guarded too: otherwise the first write is a free
    -- role assignment, and an upsert against a not-yet-existing row is an
    -- INSERT, not an UPDATE.
    IF NEW.role IS DISTINCT FROM 'user'
       AND NOT public.caller_may_write_profile_role() THEN
      RAISE EXCEPTION
        'profiles.role cannot be set on insert by this caller (attempted %); use admin_set_profile_role()', NEW.role
        USING ERRCODE = '42501';
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    -- IS DISTINCT FROM, not <>: role is NOT NULL today, but a null-safe
    -- comparison means a no-op write of the same value never trips, and a
    -- future nullable role cannot silently open a hole.
    IF NEW.role IS DISTINCT FROM OLD.role
       AND NOT public.caller_may_write_profile_role() THEN
      RAISE EXCEPTION
        'profiles.role is not self-writable (attempted % -> %); use admin_set_profile_role()', OLD.role, NEW.role
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_trip_max_members(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_trip_max_members() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_max_members  integer;
  v_member_count bigint;
BEGIN
  -- Only enforce for accepted memberships — pending/declined rows don't count.
  IF NEW.status <> 'accepted' THEN
    RETURN NEW;
  END IF;

  -- Lock the trip row for the duration of this transaction.
  -- Two concurrent INSERTs for the same trip will serialize here; the second
  -- waits until the first has committed (or rolled back) before proceeding.
  -- This ensures the COUNT below always sees the committed member set.
  SELECT max_members INTO v_max_members
  FROM trips
  WHERE id = NEW.trip_id
  FOR UPDATE;

  -- No cap set — allow unconditionally.
  IF v_max_members IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO v_member_count
  FROM trip_members
  WHERE trip_id = NEW.trip_id
    AND status  = 'accepted';

  -- BEFORE trigger: NEW row is not yet in the table, so the count reflects the
  -- committed state.  If count is already at cap, reject the insert.
  IF v_member_count >= v_max_members THEN
    RAISE EXCEPTION 'trip_full'
      USING ERRCODE = 'P0001',
            DETAIL  = 'max_members cap reached for trip ' || NEW.trip_id;
  END IF;

  RETURN NEW;
END;
$$;


