--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  insert into profiles (id, handle, username, name)
  values (
    new.id,
    lower(coalesce(new.raw_user_meta_data->>'handle', split_part(new.email,'@',1))),
    lower(coalesce(new.raw_user_meta_data->>'handle', split_part(new.email,'@',1))),
    coalesce(new.raw_user_meta_data->>'name', split_part(new.email,'@',1))
  )
  on conflict (id) do nothing;
  return new;
end
$$;


--
-- Name: in_accepted_circle(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.in_accepted_circle(viewer uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1 from circle_memberships a
    join circle_memberships b on a.user_id = b.other_id and a.other_id = b.user_id
    where a.user_id = viewer and a.other_id = target
      and a.status = 'accepted' and b.status = 'accepted'
  );
$$;


--
-- Name: increment_bucket_count(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_bucket_count(p_canonical_place_id uuid, p_bucket text, p_last_post_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
    BEGIN
    INSERT INTO place_coverage_buckets (canonical_place_id, bucket, post_count, last_post_at) VALUES (p_canonical_place_id, p_bucket, 1, p_last_post_at)
    ON CONFLICT (canonical_place_id, bucket) DO UPDATE SET post_count = place_coverage_buckets.post_count + 1, last_post_at = EXCLUDED.last_post_at;
    END;
    $$;


--
-- Name: increment_counter(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_counter(table_name text, column_name text, row_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF table_name NOT IN ('hidden_gems') OR column_name NOT IN ('save_count', 'visit_count') THEN
    RAISE EXCEPTION 'increment_counter: %.% is not allowed', table_name, column_name;
  END IF;
  EXECUTE format('UPDATE %I SET %I = COALESCE(%I, 0) + 1 WHERE id = $1', table_name, column_name, column_name)
    USING row_id;
END $_$;


--
-- Name: increment_distribution_stats(text, text, boolean, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_distribution_stats(p_item_id text, p_viewer_id text, p_negative_signal boolean, p_threshold integer DEFAULT 100, p_suppression_rate double precision DEFAULT 0.3) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_impressions INTEGER;
  v_negatives   INTEGER;
  v_new_status  TEXT;
BEGIN
  INSERT INTO content_distribution_stats (
    item_id, eligible_impressions, negative_signal_count,
    underexposure_status, first_evaluated_at, last_updated_at
  )
  VALUES (
    p_item_id,
    1,
    CASE WHEN p_negative_signal THEN 1 ELSE 0 END,
    'pending_evaluation',
    NOW(),
    NOW()
  )
  ON CONFLICT (item_id) DO UPDATE SET
    eligible_impressions  = content_distribution_stats.eligible_impressions + 1,
    negative_signal_count = content_distribution_stats.negative_signal_count
                            + CASE WHEN p_negative_signal THEN 1 ELSE 0 END,
    last_updated_at       = NOW()
  RETURNING eligible_impressions, negative_signal_count
  INTO v_impressions, v_negatives;

  IF v_impressions >= p_threshold THEN
    IF v_negatives::FLOAT / NULLIF(v_impressions, 0) >= p_suppression_rate THEN
      v_new_status := 'normal';
    ELSE
      v_new_status := 'boosting';
    END IF;
    UPDATE content_distribution_stats
       SET underexposure_status = v_new_status,
           first_evaluated_at   = COALESCE(first_evaluated_at, NOW())
     WHERE item_id = p_item_id;
  END IF;
END;
$$;


