--
-- Name: is_accepted_trip_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_accepted_trip_member(t_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1 from trip_members m
    where m.trip_id = t_id
      and m.user_id = auth.uid()
      and m.role in ('owner','member')   -- excludes 'invited'
  );
$$;


--
-- Name: is_blocked(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_blocked(a uuid, b uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM blocks
    WHERE (blocker_id = a AND blocked_id = b)
       OR (blocker_id = b AND blocked_id = a)
  );
$$;


--
-- Name: places_within_radius(double precision, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.places_within_radius(p_lat double precision, p_lng double precision, p_radius_m double precision, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, distance_m double precision)
    LANGUAGE sql STABLE
    AS $$
  WITH q AS (SELECT ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography AS g)
  SELECT p.id, ST_Distance(p.geog, q.g) AS distance_m
  FROM places p, q
  WHERE p.merged_into_place_id IS NULL AND p.geog IS NOT NULL
    AND ST_DWithin(p.geog, q.g, p_radius_m)
  ORDER BY p.geog <-> q.g
  LIMIT p_limit;
$$;


--
-- Name: post_media_path_is_moderated(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_media_path_is_moderated(p text, owner_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    p IS NOT NULL
    AND p <> ''
    AND owner_id IS NOT NULL
    -- ⚠ THE IDENTITY GATE. The caller may only ask about themselves.
    -- `auth.uid()` is already schema-qualified, which is what makes it resolve
    -- under `search_path TO ''`; it reads the request JWT rather than the
    -- current role, so SECURITY DEFINER does not change its answer.
    AND owner_id IS NOT DISTINCT FROM (SELECT auth.uid())
    AND public.post_media_path_is_owned(p, owner_id)
    AND EXISTS (
      SELECT 1 FROM public.post_media_moderation_ledger l
       WHERE l.storage_path = p
    );
$$;


--
-- Name: FUNCTION post_media_path_is_moderated(p text, owner_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_media_path_is_moderated(p text, owner_id uuid) IS 'Has this storage key ever carried a rejected/flagged verdict? SECURITY DEFINER because authenticated holds no privilege on the ledger. owner_id must equal auth.uid(): the identity is read from the JWT, not accepted from the argument list, so this cannot be called over PostgREST RPC as an oracle about another user''s keys. Returns FALSE (the permissive answer) for any session without a JWT, which is why anon and service_role hold no EXECUTE on it — server-side code must read post_media_moderation_ledger directly.';


--
-- Name: post_media_path_is_owned(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_media_path_is_owned(p text, owner_id uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT
    owner_id IS NOT NULL
    AND p IS NOT NULL
    AND p <> ''
    AND (
      -- `<uid>/…` — POST /api/media/upload (routes/posts.ts:171) and
      -- POST /api/postcards/:id/media/upload-url (routes/postcards.ts:492).
      pg_catalog.split_part(p, '/', 1) = owner_id::text
      -- `stories|memories|avatars|covers/<uid>/…` — the second branch of
      -- ownerFromPath(); reachable in post_media only for rows backfilled by
      -- 2083 from a profile-media key.
      OR (
        pg_catalog.split_part(p, '/', 1) IN ('stories', 'memories', 'avatars', 'covers')
        AND pg_catalog.split_part(p, '/', 2) = owner_id::text
      )
    );
$$;


--
-- Name: FUNCTION post_media_path_is_owned(p text, owner_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_media_path_is_owned(p text, owner_id uuid) IS 'Does this storage key belong to this user? SQL transcription of lib/mediaAccess.ts ownerFromPath(): first segment is the uid, or stories|memories|avatars|covers followed by the uid.';


--
-- Name: post_media_record_moderation_verdict(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_media_record_moderation_verdict() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  j   jsonb := pg_catalog.to_jsonb(NEW);
  rec record;
BEGIN
  FOR rec IN
    SELECT x.key_role, x.k
      FROM (VALUES
              ('original',  j ->> 'storage_path'),
              ('thumbnail', j ->> 'thumbnail_storage_path'),
              ('feed',      j ->> 'feed_storage_path')
           ) AS x(key_role, k)
     WHERE x.k IS NOT NULL AND x.k <> ''
  LOOP
    INSERT INTO public.post_media_moderation_ledger AS l
           (storage_path, storage_bucket, key_role, verdict, subject_user_id, post_media_id)
    VALUES (rec.k, NEW.storage_bucket, rec.key_role, NEW.moderation_status, NEW.user_id, NEW.id)
    ON CONFLICT (storage_path) DO UPDATE
       SET verdict         = EXCLUDED.verdict,
           storage_bucket  = COALESCE(EXCLUDED.storage_bucket, l.storage_bucket),
           key_role        = EXCLUDED.key_role,
           subject_user_id = COALESCE(EXCLUDED.subject_user_id, l.subject_user_id),
           post_media_id   = COALESCE(EXCLUDED.post_media_id, l.post_media_id),
           last_verdict_at = pg_catalog.now();
  END LOOP;

  RETURN NULL;  -- AFTER trigger: the return value is ignored.
END;
$$;


--
-- Name: FUNCTION post_media_record_moderation_verdict(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_media_record_moderation_verdict() IS 'AFTER trigger on post_media: records every rejected/flagged storage key in post_media_moderation_ledger so the verdict outlives the row, the parent post and the account.';


--
-- Name: prevent_collection_items_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_collection_items_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION
    'TRUNCATE on collection_items is not allowed. '
    'It would silently wipe every saved item for every user. '
    'Use DELETE with a WHERE clause instead.'
    USING ERRCODE = '23000'; -- integrity_constraint_violation
END;
$$;


--
-- Name: prevent_collections_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_collections_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION
    'TRUNCATE on collections is not allowed. '
    'It would bypass the is_default guard and cascade-delete every '
    'user''s saved items via collection_items ON DELETE CASCADE. '
    'Use DELETE with a WHERE clause instead.'
    USING ERRCODE = '23000'; -- integrity_constraint_violation
END;
$$;


--
-- Name: prevent_default_collection_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_default_collection_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.is_default THEN
    RAISE EXCEPTION
      'Cannot delete the default Saved collection (id: %). '
      'Set is_default = FALSE first or reassign another row as default.',
      OLD.id
      USING ERRCODE = '23000'; -- integrity_constraint_violation
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: prevent_saved_places_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_saved_places_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION
    'TRUNCATE on saved_places is not allowed. '
    'It would silently wipe every user''s wishlist. '
    'Use DELETE with a WHERE clause instead.'
