END;
$$;


--
-- Name: prevent_wishlist_places_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_wishlist_places_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
