    MESSAGE = 'TRUNCATE wishlist_places is not allowed; use DELETE … WHERE instead';
END;
$$;


--
-- Name: purge_old_ranking_debug_samples(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_ranking_debug_samples() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  deleted_count INT;
BEGIN
  DELETE FROM ranking_debug_samples
  WHERE sampled_at < now() - INTERVAL '7 days';
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: FUNCTION purge_old_ranking_debug_samples(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_old_ranking_debug_samples() IS 'Deletes ranking_debug_samples rows older than 7 days. Call nightly from the application cleanup scheduler.';


--
-- Name: rb_adjust_buddy_counter(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rb_adjust_buddy_counter(p_buddy_id uuid, p_column text, p_delta integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  IF p_column NOT IN ('completed_count', 'cancel_count', 'no_show_count') THEN
    RAISE EXCEPTION 'rb_adjust_buddy_counter: invalid column %', p_column;
  END IF;
  EXECUTE format(
    'UPDATE rent_buddy_profiles SET %I = GREATEST(0, COALESCE(%I, 0) + $1), updated_at = NOW() WHERE id = $2',
    p_column, p_column
  ) USING p_delta, p_buddy_id;
END;
$_$;


--
-- Name: rb_sync_favorites_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rb_sync_favorites_count(p_buddy_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE rent_buddy_profiles
  SET favorites_count = (
        SELECT COUNT(*) FROM rent_buddy_saved WHERE buddy_id = p_buddy_id
      ),
      updated_at = NOW()
  WHERE id = p_buddy_id;
$$;


--
-- Name: recap_write_evidence(uuid, uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recap_write_evidence(p_version_id uuid, p_place_id uuid, p_place_snapshot jsonb, p_sources jsonb, p_chapters jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO live_place_recap_sources (version_id, source_type, source_id, post_id, contributor_id, ordinal, provenance)
  SELECT p_version_id, item->>'type', (item->>'id')::uuid, NULLIF(item->>'postId','')::uuid,
    NULLIF(item->>'contributorId','')::uuid, ordinality - 1, jsonb_build_object('createdAt', item->'createdAt')
  FROM jsonb_array_elements(p_sources) WITH ORDINALITY AS source(item, ordinality);
  INSERT INTO live_place_recap_snapshots (version_id, source_id, snapshot_kind, payload)
  VALUES (p_version_id, p_place_id, 'place', p_place_snapshot);
  INSERT INTO live_place_recap_snapshots (version_id, source_id, snapshot_kind, payload)
  SELECT p_version_id, (item->>'id')::uuid, 'post', item
  FROM jsonb_array_elements(p_sources) AS source(item);
  INSERT INTO live_place_recap_chapters (version_id, ordinal, title, body, source_ids, origin)
  SELECT p_version_id, (item->>'ordinal')::int, item->>'title', item->>'body',
    ARRAY(SELECT jsonb_array_elements_text(item->'sourceIds')::uuid), item->>'origin'
  FROM jsonb_array_elements(p_chapters) AS chapter(item);
END $$;


--
-- Name: reconcile_invite_link_slots(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_invite_link_slots(min_age_minutes integer DEFAULT 5) RETURNS TABLE(link_id uuid, user_id uuid, claimed_at timestamp with time zone, trip_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row RECORD;
BEGIN
  FOR v_row IN
    SELECT
      a.link_id,
      a.user_id,
      a.claimed_at,
      til.trip_id
    FROM trip_invite_link_attempts a
    JOIN trip_invite_links til ON til.id = a.link_id
    WHERE a.claimed_at < now() - (min_age_minutes || ' minutes')::interval
      AND NOT EXISTS (
        SELECT 1
        FROM trip_members tm
        WHERE tm.trip_id = til.trip_id
          AND tm.user_id = a.user_id
      )
    FOR UPDATE OF a SKIP LOCKED
  LOOP
    -- Decrement use_count for this specific link (one decrement per stranded slot)
    UPDATE trip_invite_links
    SET use_count = GREATEST(0, use_count - 1)
    WHERE id = v_row.link_id;

    -- Remove the orphaned attempt row so retries no longer skip the slot guard
    DELETE FROM trip_invite_link_attempts
    WHERE link_id = v_row.link_id
      AND user_id = v_row.user_id;

    -- Yield this fixed slot to the caller
    link_id    := v_row.link_id;
    user_id    := v_row.user_id;
    claimed_at := v_row.claimed_at;
    trip_id    := v_row.trip_id;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: regenerate_live_place_recap(uuid, uuid, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.regenerate_live_place_recap(p_recap_id uuid, p_owner_id uuid, p_source_hash text, p_place_snapshot jsonb, p_sources jsonb DEFAULT '[]'::jsonb, p_chapters jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_recap live_place_recaps; v_prior live_place_recap_versions; v_version live_place_recap_versions;
BEGIN
  SELECT * INTO v_recap FROM live_place_recaps
    WHERE id = p_recap_id AND owner_id = p_owner_id FOR UPDATE;
  IF NOT FOUND OR v_recap.status = 'removed' THEN RAISE EXCEPTION 'recap unavailable'; END IF;
  SELECT * INTO v_prior FROM live_place_recap_versions
    WHERE id = v_recap.current_version_id AND recap_id = v_recap.id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'current version unavailable'; END IF;
  PERFORM validate_live_place_recap_evidence(
    p_owner_id, v_recap.place_day_id, v_recap.moment_id, v_recap.place_id,
    p_place_snapshot, p_sources, p_chapters
  );
  INSERT INTO live_place_recap_versions
    (recap_id, version_number, title, summary, source_hash, place_snapshot, regenerates_version_id)
    SELECT v_recap.id, COALESCE(MAX(version_number), 0) + 1, v_prior.title, '',
      p_source_hash, p_place_snapshot, v_prior.id
    FROM live_place_recap_versions WHERE recap_id = v_recap.id RETURNING * INTO v_version;
  PERFORM recap_write_evidence(v_version.id, v_recap.place_id, p_place_snapshot, p_sources, p_chapters);
  UPDATE live_place_recaps SET current_version_id = v_version.id, status = 'draft', updated_at = now()
    WHERE id = v_recap.id RETURNING * INTO v_recap;
  RETURN jsonb_build_object('recap', to_jsonb(v_recap), 'version', to_jsonb(v_version));
END $$;


--
-- Name: release_invite_link_slot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_invite_link_slot(link_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE trip_invite_links
  SET use_count = GREATEST(0, use_count - 1)
  WHERE id = link_id;
END;
$$;


