--

CREATE TABLE public.discovery_shadow_serves (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    observed_at timestamp with time zone DEFAULT now() NOT NULL,
    user_id uuid NOT NULL,
    session_id text,
    destination text NOT NULL,
    category text NOT NULL,
    radius_km numeric NOT NULL,
    page smallint NOT NULL,
    page_size smallint NOT NULL,
    sort_by text,
    serve_point smallint NOT NULL,
    cache_level text,
    legacy_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    legacy_total integer NOT NULL,
    legacy_ms integer,
    pde_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    pde_total integer NOT NULL,
    pde_ms integer,
    pde_stages jsonb DEFAULT '{}'::jsonb NOT NULL,
    pde_suppressed_writes integer DEFAULT 0 NOT NULL,
    overlap_count smallint NOT NULL,
    displaced_count smallint NOT NULL,
    top_changed boolean NOT NULL,
    engine_mode text NOT NULL,
    mode_reason text NOT NULL,
    cohort_reason text,
    cohort_bucket smallint,
    CONSTRAINT discovery_shadow_serves_serve_point_check CHECK (((serve_point >= 1) AND (serve_point <= 9)))
);


--
-- Name: TABLE discovery_shadow_serves; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.discovery_shadow_serves IS 'P1 Stage 2 shadow observations: what legacy served vs what PDE would have served, per request. Append-only (D7=A); UPDATE blocked by trigger; DELETE reachable only via the auth.users cascade. 90-day retention window, no automatic reaper.';


--
-- Name: COLUMN discovery_shadow_serves.cohort_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.discovery_shadow_serves.cohort_reason IS 'Which D6 cohort admitted this user: user_listed (A) | percent_in (B) | kind_all (C). NULL means a code path predating migration 2094, which should never occur.';


--
-- Name: COLUMN discovery_shadow_serves.cohort_bucket; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.discovery_shadow_serves.cohort_bucket IS 'The 0-99 hashed bucket for this user, present only when cohort_reason = percent_in. Lets a membership decision be re-derived from the user id rather than trusted.';


