--
-- Name: events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    host_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    location_name text,
    location_lat double precision,
    location_lng double precision,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    cover_url text,
    max_attendees integer,
    age_min integer,
    age_max integer,
    trust_score_min numeric(5,2),
    verified_only boolean DEFAULT false NOT NULL,
    visibility public.event_visibility DEFAULT 'public'::public.event_visibility NOT NULL,
    state public.event_state DEFAULT 'draft'::public.event_state NOT NULL,
    chat_thread_id uuid,
    chat_enabled boolean DEFAULT true NOT NULL,
    waitlist_enabled boolean DEFAULT true NOT NULL,
    attendee_comments_enabled boolean DEFAULT true NOT NULL,
    price_type text,
    price_url text,
    rsvp_options text[] DEFAULT '{going,maybe,interested,cant_go}'::text[] NOT NULL,
    going_count integer DEFAULT 0 NOT NULL,
    waitlist_count integer DEFAULT 0 NOT NULL,
    category text,
    city text,
    country text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    avg_rating numeric(3,1),
    review_count integer DEFAULT 0 NOT NULL,
    show_exact_location boolean DEFAULT false NOT NULL,
    rsvp_closed boolean DEFAULT false NOT NULL,
    safety_notes text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    is_recurring boolean DEFAULT false NOT NULL,
    recurring_config jsonb,
    ticket_url text,
    circle_id uuid,
    trip_id uuid,
    cover_media_type text,
    featured boolean DEFAULT false NOT NULL,
    geog public.geography(Point,4326) GENERATED ALWAYS AS (
CASE
    WHEN ((location_lat IS NOT NULL) AND (location_lng IS NOT NULL)) THEN (public.st_setsrid(public.st_makepoint(location_lng, location_lat), 4326))::public.geography
    ELSE NULL::public.geography
END) STORED,
    header_image_source text,
    header_image_status text DEFAULT 'not_requested'::text NOT NULL,
    header_image_generated_id uuid,
    header_image_attribution text,
    header_image_updated_at timestamp with time zone,
    show_header_publicly boolean DEFAULT true NOT NULL,
    cover_image_width integer,
    cover_image_height integer,
    original_language text,
    cover_source text,
    CONSTRAINT events_age_max_check CHECK (((age_max IS NULL) OR ((age_max >= 13) AND (age_max <= 100)))),
    CONSTRAINT events_age_min_check CHECK (((age_min IS NULL) OR ((age_min >= 13) AND (age_min <= 100)))),
    CONSTRAINT events_age_range_check CHECK (((age_max IS NULL) OR (age_min IS NULL) OR (age_max >= age_min))),
    CONSTRAINT events_cover_media_type_check CHECK ((cover_media_type = ANY (ARRAY['image'::text, 'video'::text]))),
    CONSTRAINT events_cover_source_check CHECK ((cover_source = ANY (ARRAY['user_upload'::text, 'ai_generated'::text]))),
    CONSTRAINT events_date_range_check CHECK (((ends_at IS NULL) OR (starts_at IS NULL) OR (ends_at >= starts_at))),
    CONSTRAINT events_description_check CHECK ((char_length(description) <= 2000)),
    CONSTRAINT events_location_name_check CHECK ((char_length(location_name) <= 300)),
    CONSTRAINT events_max_attendees_check CHECK (((max_attendees IS NULL) OR (max_attendees > 0))),
    CONSTRAINT events_price_type_check CHECK ((price_type = ANY (ARRAY['free'::text, 'external'::text]))),
    CONSTRAINT events_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 200))),
    CONSTRAINT events_trust_score_min_check CHECK (((trust_score_min IS NULL) OR ((trust_score_min >= (0)::numeric) AND (trust_score_min <= (100)::numeric))))
);


