CREATE TABLE public.message_reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    message_id uuid NOT NULL,
    reporter_id uuid NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT message_reports_reason_check CHECK ((char_length(reason) <= 200))
);


--
-- Name: message_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.message_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sender_id uuid NOT NULL,
    recipient_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    preview_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    responded_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT message_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'declined'::text, 'cancelled'::text]))),
    CONSTRAINT no_self_message_request CHECK ((sender_id <> recipient_id))
);


--
-- Name: message_thread_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.message_thread_members (
    thread_id uuid NOT NULL,
    user_id uuid NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    muted_at timestamp with time zone,
    archived_at timestamp with time zone,
    left_at timestamp with time zone,
    last_read_at timestamp with time zone,
    CONSTRAINT message_thread_members_role_check CHECK ((role = ANY (ARRAY['member'::text, 'admin'::text])))
);


--
-- Name: message_threads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.message_threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    last_message_at timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    thread_type text DEFAULT 'direct'::text NOT NULL,
    trip_id uuid,
    circle_owner_id uuid,
    title text,
    created_by uuid,
    is_e2ee boolean DEFAULT false NOT NULL,
    CONSTRAINT chk_thread_context CHECK ((((thread_type = 'trip'::text) AND (trip_id IS NOT NULL) AND (circle_owner_id IS NULL)) OR ((thread_type = 'circle'::text) AND (circle_owner_id IS NOT NULL) AND (trip_id IS NULL)) OR ((thread_type = 'direct'::text) AND (trip_id IS NULL) AND (circle_owner_id IS NULL)))),
    CONSTRAINT message_threads_status_check CHECK ((status = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT message_threads_thread_type_check CHECK ((thread_type = ANY (ARRAY['direct'::text, 'trip'::text, 'circle'::text])))
);


