    CONSTRAINT moderation_reports_status_check CHECK ((status = ANY (ARRAY['open'::text, 'reviewing'::text, 'actioned'::text, 'dismissed'::text]))),
    CONSTRAINT moderation_reports_subject_type_check CHECK ((subject_type = ANY (ARRAY['user'::text, 'post'::text, 'comment'::text, 'message'::text, 'event'::text, 'review'::text, 'buddy_listing'::text, 'media'::text, 'place'::text])))
);


