--
-- Name: places; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.places (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    normalized_name text NOT NULL,
    primary_category text DEFAULT 'other'::text NOT NULL,
    latitude double precision,
    longitude double precision,
    address text,
    city text,
    neighborhood text,
    country_code text,
    canonical_location_id uuid,
    status text DEFAULT 'active'::text NOT NULL,
    merged_into_place_id uuid,
    field_freshness jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    geog public.geography(Point,4326) GENERATED ALWAYS AS (
CASE
    WHEN ((latitude IS NOT NULL) AND (longitude IS NOT NULL)) THEN (public.st_setsrid(public.st_makepoint(longitude, latitude), 4326))::public.geography
    ELSE NULL::public.geography
END) STORED,
    image_source_type text,
    image_accuracy_status text DEFAULT 'unverified'::text NOT NULL,
    header_image_generated_id uuid,
    CONSTRAINT places_status_check CHECK ((status = ANY (ARRAY['active'::text, 'closed'::text, 'temporarily_closed'::text, 'moved'::text, 'duplicate'::text, 'unverified'::text])))
);


