    content text DEFAULT ''::text NOT NULL,
    media_urls text[] DEFAULT '{}'::text[] NOT NULL,
    visibility public.post_visibility DEFAULT 'public'::public.post_visibility NOT NULL,
    status public.post_status DEFAULT 'active'::public.post_status NOT NULL,
    created_by uuid,
    updated_by uuid,
    source text DEFAULT 'api_server'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    media_type text,
    location_name text,
    location_place_id text,
    location_city text,
    location_country text,
    location_lat numeric,
    location_lng numeric,
    user_gps_lat numeric,
    user_gps_lng numeric,
    location_source public.location_source DEFAULT 'none'::public.location_source NOT NULL,
    location_verified boolean DEFAULT false NOT NULL,
    location_verified_at timestamp with time zone,
    location_distance_meters numeric,
    add_to_passport boolean DEFAULT true NOT NULL,
    like_count integer DEFAULT 0 NOT NULL,
    comment_count integer DEFAULT 0 NOT NULL,
    share_count integer DEFAULT 0 NOT NULL,
    location_privacy_mode public.post_location_privacy_mode DEFAULT 'none'::public.post_location_privacy_mode NOT NULL,
    geotag_verified boolean DEFAULT false NOT NULL,
    geotag_credit_awarded boolean DEFAULT false NOT NULL,
    original_lat double precision,
    original_lng double precision,
    public_lat double precision,
    public_lng double precision,
    venue_id text,
    venue_name text,
    public_location_label text,
    geofence_radius_meters integer DEFAULT 400 NOT NULL,
    publish_after_exit boolean DEFAULT false NOT NULL,
    publish_after_time timestamp with time zone,
    exited_geofence_at timestamp with time zone,
    publish_eligible_at timestamp with time zone,
    published_at timestamp with time zone,
    location_sensitivity_level public.location_sensitivity_level DEFAULT 'low'::public.location_sensitivity_level NOT NULL,
    post_status public.delayed_post_status DEFAULT 'published'::public.delayed_post_status NOT NULL,
    delayed_location_reason text,
    comments_setting text DEFAULT 'everyone'::text NOT NULL,
    likes_hidden boolean DEFAULT false NOT NULL,
    sharing_disabled boolean DEFAULT false NOT NULL,
    reposting_disabled boolean DEFAULT false NOT NULL,
    category text,
    save_count integer DEFAULT 0 NOT NULL,
    media_thumbnail_url text,
    primary_media_type text,
    media_count integer DEFAULT 0 NOT NULL,
    has_video boolean DEFAULT false NOT NULL,
    canonical_location_id uuid,
    filter_id text DEFAULT 'original'::text NOT NULL,
    filter_intensity integer DEFAULT 100 NOT NULL,
    media_duration_seconds numeric,
    geog public.geography(Point,4326) GENERATED ALWAYS AS (
CASE
    WHEN ((location_lat IS NOT NULL) AND (location_lng IS NOT NULL)) THEN (public.st_setsrid(public.st_makepoint((location_lng)::double precision, (location_lat)::double precision), 4326))::public.geography
    ELSE NULL::public.geography
END) STORED,
    canonical_place_id uuid,
    post_buckets text[],
    bucket_classified boolean DEFAULT false NOT NULL,
    original_language text,
    publish_at timestamp with time zone,
    geo_restriction text,
    age_restriction_enabled boolean DEFAULT false NOT NULL,
    age_min smallint,
    age_max smallint,
    CONSTRAINT posts_comments_setting_check CHECK ((comments_setting = ANY (ARRAY['everyone'::text, 'friends'::text, 'circle'::text, 'trip_crew'::text, 'verified'::text, 'disabled'::text]))),
    CONSTRAINT posts_has_body CHECK (((content <> ''::text) OR (array_length(media_urls, 1) >= 1))),
    CONSTRAINT posts_trip_only_requires_trip CHECK (((visibility <> 'trip_only'::public.post_visibility) OR (trip_id IS NOT NULL)))
);


