--
-- Name: public_profile_verification; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.public_profile_verification AS
 SELECT id AS profile_id,
    verification_status,
    verification_level,
    verified_since,
        CASE
            WHEN ((verification_status = 'verified'::text) AND (id_verified_at IS NOT NULL)) THEN true
            ELSE false
        END AS id_verified,
        CASE
            WHEN ((verification_status = 'verified'::text) AND (selfie_verified_at IS NOT NULL)) THEN true
            ELSE false
        END AS selfie_matched,
        CASE
            WHEN ((verification_status = 'verified'::text) AND (home_country_verified_at IS NOT NULL)) THEN true
            ELSE false
        END AS home_country_verified,
        CASE
            WHEN ((verification_status = 'verified'::text) AND (safety_flags_count = 0)) THEN true
            ELSE false
        END AS no_safety_flags,
        CASE
            WHEN (host_verified_at IS NOT NULL) THEN true
            ELSE false
        END AS host_verified,
        CASE
            WHEN (buddy_verified_at IS NOT NULL) THEN true
            ELSE false
        END AS buddy_verified
   FROM public.profiles;


