--

CREATE POLICY highlights_insert ON public.highlights FOR INSERT WITH CHECK ((auth.uid() = owner_id));


--
-- Name: highlights highlights_insert_own; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY highlights_insert_own ON public.highlights FOR INSERT TO authenticated WITH CHECK ((owner_id = auth.uid()));


--
-- Name: highlights highlights_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY highlights_select ON public.highlights FOR SELECT USING (((deleted_at IS NULL) AND (expires_at > now()) AND ((owner_id = auth.uid()) OR ((NOT public.viewer_is_blocked(owner_id)) AND ((visibility = ANY (ARRAY['public'::text, 'travelers_nearby'::text])) OR ((visibility = 'circle_only'::text) AND (public.in_accepted_circle(auth.uid(), owner_id) OR (EXISTS ( SELECT 1
   FROM public.user_friendships
  WHERE (((user_friendships.user_a = auth.uid()) AND (user_friendships.user_b = highlights.owner_id)) OR ((user_friendships.user_b = auth.uid()) AND (user_friendships.user_a = highlights.owner_id))))))))))));


--
-- Name: highlights highlights_select_active; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY highlights_select_active ON public.highlights FOR SELECT TO authenticated USING (((deleted_at IS NULL) AND (expires_at > now()) AND (NOT public.is_blocked(auth.uid(), owner_id)) AND ((owner_id = auth.uid()) OR (visibility = ANY (ARRAY['public'::text, 'travelers_nearby'::text])) OR ((visibility = 'circle_only'::text) AND (EXISTS ( SELECT 1
   FROM public.circle_memberships cm
  WHERE ((cm.user_id = highlights.owner_id) AND (cm.other_id = auth.uid()))))) OR ((visibility = 'trip_only'::text) AND (EXISTS ( SELECT 1
   FROM (public.trip_members tm1
     JOIN public.trip_members tm2 ON ((tm1.trip_id = tm2.trip_id)))
  WHERE ((tm1.user_id = highlights.owner_id) AND (tm2.user_id = auth.uid()))))))));


