CREATE POLICY profiles_insert ON public.profiles FOR INSERT WITH CHECK ((id = auth.uid()));


--
-- Name: profiles profiles_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY profiles_select ON public.profiles FOR SELECT USING (((id = auth.uid()) OR ((is_private = false) AND (NOT public.viewer_is_blocked(id))) OR ((NOT public.viewer_is_blocked(id)) AND (EXISTS ( SELECT 1
   FROM public.user_friendships
  WHERE (((user_friendships.user_a = auth.uid()) AND (user_friendships.user_b = profiles.id)) OR ((user_friendships.user_b = auth.uid()) AND (user_friendships.user_a = profiles.id))))))));


