-- Name: quick_availability_status qas_circle_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY qas_circle_select ON public.quick_availability_status FOR SELECT USING (((expires_at > now()) AND (EXISTS ( SELECT 1
   FROM public.circle_memberships
  WHERE (((circle_memberships.user_id = quick_availability_status.user_id) AND (circle_memberships.other_id = auth.uid())) OR ((circle_memberships.other_id = quick_availability_status.user_id) AND (circle_memberships.user_id = auth.uid())))))));


--
-- Name: quick_availability_status qas_friends_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY qas_friends_select ON public.quick_availability_status FOR SELECT USING (((expires_at > now()) AND (EXISTS ( SELECT 1
   FROM public.user_friendships
  WHERE (((user_friendships.user_a = auth.uid()) AND (user_friendships.user_b = quick_availability_status.user_id)) OR ((user_friendships.user_b = auth.uid()) AND (user_friendships.user_a = quick_availability_status.user_id)))))));


--
-- Name: quick_availability_status qas_own; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY qas_own ON public.quick_availability_status USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));


--
-- Name: quick_availability_status qas_trip_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY qas_trip_select ON public.quick_availability_status FOR SELECT USING (((expires_at > now()) AND (EXISTS ( SELECT 1
   FROM (public.trip_members tm1
     JOIN public.trip_members tm2 ON ((tm1.trip_id = tm2.trip_id)))
  WHERE ((tm1.user_id = auth.uid()) AND (tm1.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role])) AND (tm2.user_id = quick_availability_status.user_id) AND (tm2.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role])))))));


