--

CREATE POLICY route_legs_member_select ON public.route_legs FOR SELECT USING ((EXISTS ( SELECT 1
   FROM (public.route_plans rp
     JOIN public.trip_members tm ON ((tm.trip_id = rp.trip_id)))
  WHERE ((rp.id = route_legs.route_plan_id) AND (tm.user_id = auth.uid()) AND (tm.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role])) AND (rp.trip_id IS NOT NULL)))));


