-- Name: trip_availability ta_own; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ta_own ON public.trip_availability USING (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM public.trip_members
  WHERE ((trip_members.trip_id = trip_availability.trip_id) AND (trip_members.user_id = auth.uid()) AND (trip_members.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role]))))))) WITH CHECK (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM public.trip_members
  WHERE ((trip_members.trip_id = trip_availability.trip_id) AND (trip_members.user_id = auth.uid()) AND (trip_members.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role])))))));


--
-- Name: trip_availability ta_trip_members_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ta_trip_members_select ON public.trip_availability FOR SELECT USING ((EXISTS ( SELECT 1
   FROM (public.trip_members tm1
     JOIN public.trip_members tm2 ON ((tm1.trip_id = tm2.trip_id)))
  WHERE ((tm1.user_id = auth.uid()) AND (tm1.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role])) AND (tm2.user_id = trip_availability.user_id) AND (tm2.trip_id = trip_availability.trip_id) AND (tm2.role = ANY (ARRAY['owner'::public.member_role, 'member'::public.member_role]))))));


